const response = $input.first().json;
const people = response.people || [];

if (people.length === 0) {
  return [{ json: { error: 'No leads returned from Apollo', count: 0 } }];
}

return people.map(person => ({
  json: {
    lead_id: person.id || '',
    full_name: person.name || '',
    first_name: person.first_name || '',
    prospect_email: person.email || '',
    job_title: person.title || '',
    company_name: person.organization?.name || '',
    corporate_website: person.organization?.website_url || '',
    linkedin_url: person.linkedin_url || '',
    employee_count: person.organization?.employee_count || 0
  }
}));

const leadData = $('Extract Lead Array').item.json;
let rawHtml = $json.data || $json.body || '';

// If scrape failed or returned error, use company name as minimal context
if (!rawHtml || rawHtml.length < 100) {
  return {
    json: {
      ...leadData,
      compressed_web_context: `Company: ${leadData.company_name}. No additional website context available.`,
      scrape_success: false
    }
  };
}

// Strip all non-content elements
let cleanText = rawHtml
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<noscript[^>]*>[\s\S]*?<\/noscript>/gi, '')
  .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
  .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
  .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
  .replace(/<form[^>]*>[\s\S]*?<\/form>/gi, '')
  .replace(/<!--[\s\S]*?-->/g, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 4000);

return {
  json: {
    ...leadData,
    compressed_web_context: cleanText,
    scrape_success: true,
    context_length: cleanText.length
  }
};

