=Write a hyper-personalized B2B cold email introduction for this prospect.

PROSPECT DATA:
- Name: {{ $json.first_name }} {{ $json.full_name }}
- Job Title: {{ $json.job_title }}
- Company: {{ $json.company_name }}
- Website: {{ $json.corporate_website }}
- Employees: {{ $json.employee_count }}

WEBSITE CONTEXT (scraped from their homepage):
{{ $json.compressed_web_context }}

Write a 3-sentence cold email body AND a subject line. Output as JSON with keys: 'subject', 'email_body'.

parameters.jsCode:
const agentOutput = $json.output || '';
let parsed = { subject: '', email_body: '' };

try {
  // The agent may return JSON directly or wrapped in markdown
  const jsonMatch = agentOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    parsed = JSON.parse(agentOutput);
  }
} catch (e) {
  // Fallback: try to extract from plain text
  const lines = agentOutput.split('\n').filter(l => l.trim());
  parsed.subject = lines[0]?.replace(/^subject:/i, '').trim() || 'Quick note for you';
  parsed.email_body = lines.slice(1).join('\n').trim();
}

// Build the full email with compliance footer
const leadData = $('HTML Compressor & Context Extractor').item.json;
const complianceFooter = `\n\n---\nThis email was sent to ${leadData.prospect_email} based on your professional profile. If you prefer not to receive messages like this, simply reply with "unsubscribe" and you will not be contacted again.`;

const fullBody = (parsed.email_body || '') + complianceFooter;

return {
  json: {
    ...leadData,
    email_subject: parsed.subject || 'A thought on your platform',
    email_body_text: fullBody,
    email_body_html: `<html><body style="font-family:Arial,sans-serif;max-width:600px;line-height:1.6;color:#333;">${fullBody.replace(/\n/g, '<br>')}</body></html>`
  }
};

