// Randomized delay between 300s (5 min) and 900s (15 min)
// This mimics natural human email sending patterns
const minDelay = 300;
const maxDelay = 900;
const delaySeconds = Math.floor(Math.random() * (maxDelay - minDelay + 1)) + minDelay;

return {
  json: {
    ...$json,
    delay_seconds: delaySeconds,
    delay_minutes: (delaySeconds / 60).toFixed(1)
  }
};

const errorData = {
  pipeline: 'B2B_OUTBOUND',
  executionId: $execution?.id || 'unknown',
  timestamp: new Date().toISOString(),
  errorMessage: $json.error?.message || $json.error?.description || 'Unknown error',
  failedNode: $json.error?.node?.name || 'unknown',
  workflowName: 'Pipeline 3 - B2B Outreach Fabric'
};
return [{ json: errorData }];
